function validate([n, k]) {
  if (!Number.isInteger(n) || n < 1 || n > 100000) return 'n is between 1 and 10^5.';
  if (!Number.isInteger(k) || k < 1 || k > 9) return 'k is between 1 and 9.';
  return null;
}

