function largestPalindrome(n, k) {
  const digits = new Array(n).fill(9);
  const setPair = (i, d) => {
    digits[i] = d;
    digits[n - 1 - i] = d;
  };
  const remainder = () => {
    let rest = 0;
    for (const digit of digits) {
      rest = (rest * 10 + digit) % k;
    }
    return rest;
  };
  if (k === 2 || k === 4 || k === 8) {
    const edge = k === 2 ? 1 : k === 4 ? 2 : 3;
    for (let i = 0; i < edge && i < n; i++) {
      setPair(i, 8);
    }
  } else if (k === 5) {
    setPair(0, 5);
  } else if (k === 6 || k === 7) {
    if (k === 6) {
      setPair(0, 8);
    }
    const middle = Math.floor((n - 1) / 2);
    for (let d = 9; d >= 0; d--) {
      setPair(middle, d);
      if (remainder() === 0) {
        break;
      }
    }
  }
  return digits.join('');
}

