function largestPalindrome(n, k) {
  // Palindromes with n digits are ordered by their first half, so walk the halves downwards.
  const half = Math.ceil(n / 2);
  for (let first = 10 ** half - 1; first >= 10 ** (half - 1); first--) {
    const front = String(first);
    const back = front.slice(0, n - half).split('').reverse().join('');
    const candidate = front + back;
    if (BigInt(candidate) % BigInt(k) === 0n) return candidate;
  }
  return 'none';
}

