function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    // Mostly 6 and 7, whose middle digits need a search.
    const k = rand() < 0.6 ? int(6, 7) : int(1, 9);
    return [int(9000, 10000), k];
  }
  return [int(1, 8), int(1, 9)];
}
